const journal=[{img:"assets/story.jpg",en:"The art of a generous Saudi table",ar:"فن المائدة السعودية الكريمة",tag:"HOSPITALITY"},{img:"assets/grill.jpg",en:"From the fire to your family",ar:"من النار إلى مائدتكم",tag:"KITCHEN"},{img:"assets/feast.jpg",en:"How to plan the perfect feast",ar:"كيف تخططون للوليمة المثالية",tag:"GATHERINGS"}];
let data=load(),lang=localStorage.getItem("nuzha-lang")||"en",filter="all";
function load(){try{return {...defaults,...JSON.parse(localStorage.getItem("nuzha-data"))}}catch{return structuredClone(defaults)}}
function tr(k){return i18n[lang][k]||k}function setLang(l){lang=l;localStorage.setItem("nuzha-lang",l);document.documentElement.lang=l;document.documentElement.dir=l==="ar"?"rtl":"ltr";document.querySelector("#langBtn").textContent=l==="en"?"العربية":"English";document.querySelectorAll("[data-t]").forEach(e=>e.textContent=tr(e.dataset.t));renderAll()}
function renderMenu(){const cats=["all",...new Set(data.menu.map(x=>x.cat))];filters.innerHTML=cats.map(c=>`<button class="filter-btn ${filter===c?'active':''}" data-filter="${c}">${tr(c)}</button>`).join("");menuGrid.innerHTML=data.menu.filter(x=>filter==="all"||x.cat===filter).map(x=>`<article class="menu-card"><img src="${x.img}" alt="${lang==='ar'?x.ar:x.en}"><div class="menu-info"><div class="menu-meta"><small>${tr(x.cat)}</small><strong>${lang==='ar'?x.priceAr:x.price}</strong></div><h3>${lang==='ar'?x.ar:x.en}</h3><p>${lang==='ar'?x.descAr:x.descEn}</p></div></article>`).join("");filters.querySelectorAll("button").forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderMenu()})}
function renderReviews(){quoteTrack.innerHTML=data.reviews.map(r=>`<article class="quote"><div class="stars">★★★★★</div><blockquote>“${lang==='ar'?r.ar:r.en}”</blockquote><footer>${r.name}</footer></article>`).join("")}
function renderJournal(){journalGrid.innerHTML=journal.map(j=>`<article class="journal-card"><img src="${j.img}" alt=""><small>${j.tag}</small><h3>${lang==='ar'?j.ar:j.en}</h3></article>`).join("")}
function renderSocials(){document.querySelectorAll("[data-social]").forEach(a=>a.href=data.socials?.[a.dataset.social]||"#")}
function renderAll(){renderMenu();renderReviews();renderJournal();renderSocials()}
function applyTheme(){document.body.classList.remove("theme-night","theme-rose");if(data.theme===1)document.body.classList.add("theme-night");if(data.theme===2)document.body.classList.add("theme-rose")}
themeBtn.onclick=()=>{data.theme=(data.theme+1)%3;applyTheme();save()};langBtn.onclick=()=>setLang(lang==="en"?"ar":"en");document.querySelector(".menu-toggle").onclick=e=>{const n=document.querySelector(".site-header nav");n.classList.toggle("open");e.currentTarget.setAttribute("aria-expanded",n.classList.contains("open"))};document.querySelectorAll("nav a").forEach(a=>a.onclick=()=>document.querySelector(".site-header nav").classList.remove("open"));
const io=new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&e.target.classList.add("visible")),{threshold:.12});document.querySelectorAll(".reveal").forEach(e=>io.observe(e));
const dlg=document.querySelector("#adminDialog"),content=document.querySelector("#adminContent");adminBtn.onclick=()=>{renderAdmin("menu");dlg.showModal()};document.querySelectorAll(".admin-tabs button").forEach(b=>b.onclick=()=>{document.querySelectorAll(".admin-tabs button").forEach(x=>x.classList.remove("active"));b.classList.add("active");renderAdmin(b.dataset.tab)});
function renderAdmin(tab){if(tab==="menu")content.innerHTML=data.menu.map((x,i)=>`<div class="admin-row"><input value="${x.en}" data-i="${i}" data-k="en" aria-label="English item name"><input value="${x.ar}" data-i="${i}" data-k="ar" aria-label="Arabic item name"><input value="${x.price}" data-i="${i}" data-k="price" aria-label="Price"><button type="button" class="delete-row" data-i="${i}">×</button></div>`).join("")+`<button type="button" class="add-row" id="addMenu">+ Add menu item</button>`;else if(tab==="reviews")content.innerHTML=data.reviews.map((x,i)=>`<div class="admin-row"><textarea data-i="${i}" data-k="en">${x.en}</textarea><textarea data-i="${i}" data-k="ar">${x.ar}</textarea><input value="${x.name}" data-i="${i}" data-k="name"><button type="button" class="delete-row" data-i="${i}">×</button></div>`).join("")+`<button type="button" class="add-row" id="addReview">+ Add review</button>`;else content.innerHTML=`<div class="settings-form"><label>WhatsApp phone<input id="adminPhone" value="${data.phone}"></label><label>Facebook URL<input id="adminFacebook" type="url" value="${data.socials?.facebook||''}"></label><label>Google Business URL<input id="adminGoogle" type="url" value="${data.socials?.google||''}"></label><label>TikTok URL<input id="adminTiktok" type="url" value="${data.socials?.tiktok||''}"></label><label>Theme<select id="adminTheme"><option value="0">Saffron Garden</option><option value="1">Midnight Majlis</option><option value="2">Rose Souk</option></select></label><p>Tip: use Export JSON as a portable content backup.</p></div>`,document.querySelector("#adminTheme").value=data.theme;
 content.querySelectorAll("input[data-i],textarea[data-i]").forEach(el=>el.oninput=()=>data[tab][+el.dataset.i][el.dataset.k]=el.value);content.querySelectorAll(".delete-row").forEach(b=>b.onclick=()=>{data[tab].splice(+b.dataset.i,1);renderAdmin(tab)});if(document.querySelector("#addMenu"))addMenu.onclick=()=>{data.menu.push({id:Date.now(),en:"New dish",ar:"طبق جديد",descEn:"Add a short description.",descAr:"أضف وصفاً قصيراً.",price:"Ask us",priceAr:"حسب الطلب",cat:"Feasts",img:"assets/hero.jpg"});renderAdmin("menu")};if(document.querySelector("#addReview"))addReview.onclick=()=>{data.reviews.push({en:"Add verified guest feedback.",ar:"أضف رأي ضيف موثق.",name:"Guest"});renderAdmin("reviews")}}
function save(){localStorage.setItem("nuzha-data",JSON.stringify(data));renderAll()}saveData.onclick=()=>{if(document.querySelector("#adminPhone")){data.phone=adminPhone.value;data.socials={facebook:adminFacebook.value,google:adminGoogle.value,tiktok:adminTiktok.value};data.theme=+adminTheme.value;applyTheme()}save();dlg.close()};resetData.onclick=()=>{if(confirm("Reset all local edits?")){data=structuredClone(defaults);localStorage.removeItem("nuzha-data");applyTheme();renderAll();renderAdmin("menu")}};exportData.onclick=()=>{const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:"application/json"}));a.download="nuzha-content.json";a.click()};importData.onchange=async e=>{try{data=JSON.parse(await e.target.files[0].text());save();renderAdmin("menu");alert("Content imported") }catch{alert("Could not import this file")}};
